from itertools import product
from sympy import Mul, itermonomials, symbols

x, y, z = symbols('x y z')
a, b = symbols('a b', commutative=False)
for variables in ([x, y, z], [a, b], [x, a, b]):
    for maximum in range(5):
        for minimum in range(maximum + 2):
            expected = {
                Mul(*word)
                for degree in range(minimum, maximum + 1)
                for word in product(variables, repeat=degree)
            }
            actual = set(itermonomials(variables, maximum, minimum))
            assert actual == expected, (variables, maximum, minimum)
result = set(itermonomials([x, y, z], 3, 3))
assert len(result) == 10
assert x*y*z in result and x*y**2 in result
print('Degree-range checks passed for commutative, noncommutative, and mixed variables; all 10 cubic monomials returned.')
